describe('Login Page - Password Mistyping Error Handling', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display clear failure message when password is mistyped', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill in the username
    cy.get('[name="username"]').type('tomsmith');

    // Fill in the password with a mistyped value
    cy.get('[name="password"]').type('wrongpassword');

    // Submit the form
    cy.get('[type="submit"]').click();

    // Wait for the API response
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });

    // Verify the flash error message is displayed
    cy.get('[data-testid="flash-messages"]').should('be.visible');
    cy.get('[data-testid="flash-error"]').should('contain', 'Your password is invalid!');

    // Verify the user is not redirected
    cy.url().should('include', '/login');

    // Verify the error message is clear and not generic
    cy.get('[data-testid="flash-error"]').should('have.css', 'color', 'red');
    cy.get('[data-testid="flash-error"]').should('not.contain', 'An error occurred');
  });

  it('should not display error message when password is correct', () => {
    // Fill in the username
    cy.get('[name="username"]').type('tomsmith');

    // Fill in the password with a correct value
    cy.get('[name="password"]').type('correctpassword123');

    // Submit the form
    cy.get('[type="submit"]').click();

    // Wait for the API response
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify the user is redirected to the dashboard
    cy.url().should('include', '/dashboard');

    // Verify the flash error message is not displayed
    cy.get('[data-testid="flash-messages"]').should('not.exist');
  });
});
